css:
.sd { --sd-gold: #D9B25F; display: flex; flex-direction: column; align-items: center; gap: var(--os-space-xs); text-align: center; }
.sd__emblem { display: none; width: min(520px, 100%); height: auto; fill: none; stroke: var(--sd-gold); stroke-width: 1.1; stroke-linecap: round; filter: drop-shadow(0 0 10px color-mix(in oklab, var(--sd-gold) 45%, transparent)); }
.sd[data-emblem="seed"] .sd__emblem--seed, .sd[data-emblem="winged-sun"] .sd__emblem--winged-sun, .sd[data-emblem="eye"] .sd__emblem--eye { display: block; }
.sd__fill { fill: var(--sd-gold); stroke: none; }
.sd__fill--soft { fill: color-mix(in oklab, var(--sd-gold) 22%, transparent); stroke: var(--sd-gold); }
.sd__seed { stroke-width: .9; }
.sd__dots { stroke-dasharray: .8 3; }
.sd__line { margin: 0; font-family: var(--os-font-heading); font-style: italic; font-size: var(--os-type-h3-font-size); color: var(--os-color-heading); }
